import{_ as i,o as e,c as r,aw as l}from"./chunks/framework.DLufY-ao.js";const S=JSON.parse('{"title":"Critical Rendering Path","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md","filePath":"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md"}'),t={name:"wiki/dev-commit/js/critical-rendering-path/rendering/critical-rendering-path.md"};function n(o,a,c,h,d,s){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="critical-rendering-path" tabindex="-1">Critical Rendering Path <a class="header-anchor" href="#critical-rendering-path" aria-label="Permalink to &quot;Critical Rendering Path&quot;">​</a></h1><h2 id="critical-rendering-path-1" tabindex="-1">Critical Rendering Path <a class="header-anchor" href="#critical-rendering-path-1" aria-label="Permalink to &quot;Critical Rendering Path&quot;">​</a></h2><ul><li><strong>Critical Rendering Path</strong> (Критический путь рендеринга) - последовательность шагов, необходимая для первого отображения страницы (прежде чем HTML-ответ от сервера будет преобразован в пиксели на экране)</li><li>Знания о CRP необходимы для улчшения производительности</li></ul><h2 id="данные" tabindex="-1">Данные <a class="header-anchor" href="#данные" aria-label="Permalink to &quot;Данные&quot;">​</a></h2><ul><li>Style Calculation - вычисление стилей для каждого элемента</li><li>Render 16ms</li></ul><h2 id="изображения" tabindex="-1">Изображения <a class="header-anchor" href="#изображения" aria-label="Permalink to &quot;Изображения&quot;">​</a></h2><hr><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><h3 id="_1-построение-dom-дерева-✅" tabindex="-1">1. Построение DOM-дерева ✅ <a class="header-anchor" href="#_1-построение-dom-дерева-✅" aria-label="Permalink to &quot;1. Построение DOM-дерева ✅&quot;">​</a></h3><ul><li>Из полученного от сервера HTML-документа формируется DOM</li><li><strong>DOM</strong> (объектная модель документа) дерево это объект, представляющий полностью разобранную HTML-страницу. Начиная с корневого элемента html, узлы создаются для каждого элемента/текста на странице. Элементы, вложенные в другие элементы, представлены в виде дочерних узлов, и каждый узел содержит полный набор атрибутов для этого элемента</li><li>HTML может быть исполнен по частям. Документ не должен быть загружен полностью для того, чтобы контент начал появляться на странице</li><li>DOM-дерево помещается в JavaScript-объект Document</li></ul><hr><h3 id="_2-построение-cssom-дерева-❌" tabindex="-1">2. Построение CSSOM-дерева ❌ <a class="header-anchor" href="#_2-построение-cssom-дерева-❌" aria-label="Permalink to &quot;2. Построение CSSOM-дерева ❌&quot;">​</a></h3><ul><li>Загружаются и распознаются стили, формируется CSSOM</li><li>Строится параллельно с построением DOM</li><li><strong>CSSOM</strong> (CSS Object Model) - объект, представляющий стили, связанные с DOM. Он выглядит так же как DOM, но с соответствующими стилями для каждого узла. Не имеет значения были ли стили объявлены явно или наследуются</li><li>CSS считается «блокирующим обработку ресурсом». Это значит, что Render-дерево не может быть построено без полного первоначального разбора CSS</li><li>В отличии от HTML, CSS не может быть использован по частям в силу своей каскадной природы. Стили, описанные в документе ниже, могут переопределять и изменять стили, определённые ранее. Так что если мы начнём использовать CSS-стили до того, как будет разобрана таблица стилей, мы можем столкнуться с ситуацией, когда стили будут применяться неверно. Это означает, что для перехода к следующему шагу, необходимо полностью разобрать CSS</li></ul><p>CSSOM перестраивается полностью каждый раз---</p><h3 id="_3-запуск-javascript-❌-при-async-✅" tabindex="-1">3. Запуск JavaScript ❌ при async ✅ <a class="header-anchor" href="#_3-запуск-javascript-❌-при-async-✅" aria-label="Permalink to &quot;3. Запуск JavaScript ❌ при async ✅&quot;">​</a></h3><ul><li>JavaScript является блокирующим ресурсом для парсера. Это означает, что JavaScript блокирует разбор самого HTML-документа</li><li>Когда парсер доходит до тега script (не важно внутренний он или внешний), он останавливается, забирает файл (если он внешний) и запускает его</li><li>JavaScript можно загружать асинхронно, указав атрибут async, для того, чтобы избежать блокировки парсера</li></ul><hr><h3 id="_4-создание-render-tree" tabindex="-1">4. Создание Render Tree <a class="header-anchor" href="#_4-создание-render-tree" aria-label="Permalink to &quot;4. Создание Render Tree&quot;">​</a></h3><ul><li><strong>Render-дерево</strong> - совокупность DOM и CSSOM</li><li>Это дерево, которое даёт представление о том, что в конечном итоге будет отображено на странице. Это означает, что оно захватывает только видимый контент и не включает, например, элементы, которые были скрыты с помощью CSS-правила display: none или &lt;head&gt;</li></ul><hr><h3 id="_5-layout-генерация-раскладки" tabindex="-1">5. Layout (генерация раскладки) <a class="header-anchor" href="#_5-layout-генерация-раскладки" aria-label="Permalink to &quot;5. Layout (генерация раскладки)&quot;">​</a></h3><ul><li><strong>Раскладка</strong> - для каждого элемента Render Tree определяютяс его размеры и рассчитывается его положение на странице</li><li>Вычисление взаимного расположения и размеров элементов на странице, плюс компоновка всего</li><li>Браузеры используют поточный метод (flow), при котором в большинстве случаев достаточно одного прохода для размещения всех элементов (для таблиц проходов требуется больше)</li><li>Определяется размер видимой области документа (viewport), которая обеспечивает контекст для стилей CSS, зависимых от него, например, проценты или единицы viewport</li><li>Размер viewport определяется метатэгом, находящемся в head документа или, если тэг не представлен, будет использовано стандартное значение viewport 980px</li></ul><hr><h3 id="_6-paint-отрисовка-в-браузере" tabindex="-1">6. Paint (отрисовка в браузере) <a class="header-anchor" href="#_6-paint-отрисовка-в-браузере" aria-label="Permalink to &quot;6. Paint (отрисовка в браузере)&quot;">​</a></h3><ul><li><strong>Отрисовка</strong> - видимый контент страницы преобразуется в пиксели и отрисовывается на экране</li><li>Время, которое займет этот этап, зависит как от величины DOM, так и от того, какие стили применяются. Некоторые стили требуют больше усилий, чтобы быть применёнными, чем другие. Например, сложное градиентное фоновое изображение потребует больше времени, чем простой сплошной цвет на фоне</li></ul><h2 id="chrome-dev-tools" tabindex="-1">Chrome Dev Tools <a class="header-anchor" href="#chrome-dev-tools" aria-label="Permalink to &quot;Chrome Dev Tools&quot;">​</a></h2><ul><li>Chrome Dev Tools ➝ Performance ➝ Event Log</li><li>Chrome Dev Tools ➝ Network ➝ Record network activity</li></ul><ol><li>Send Request - GET-запрос, отправленный для index.html</li><li>Parse HTML and Send Request - начать разбор HTML и построение DOM. Отправить GET запрос для style.css и main.js</li><li>Parse Stylesheet - CSSOM, созданный для style.css</li><li>Evaluate Script - вычислить (выполнить) main.js</li><li>Layout - генерация раскладки, основанной на значении метатега viewport</li><li>Paint - отрисовка пикселей в документе</li></ol>',28)])])}const m=i(t,[["render",n]]);export{S as __pageData,m as default};
